-- Responsibility: disposable catalog/media HTTP acceptance witnesses only.
-- Dependencies: all forward migrations; check_catalog_api.sh is the sole caller.
-- Invariant: fixed fixture IDs never go to a production database.
\set ON_ERROR_STOP on
-- Disposable C07 acceptance fixture, administered by root only. Never production.
-- API value IDs omit option_id, so duplicate IDs across options are ambiguous.
-- One-option product with 45 deterministic values (id = md5('c07-page-'||n)) for variant paging.
SELECT '11111111-1111-4111-8111-111111111111','33333333-3333-4333-8333-333333333337','44444444-4444-4444-8444-444444444444',
 md5('c07-page-'||n)::uuid,'PAGE-'||n,'Page '||n FROM generate_series(1,45) AS n ON CONFLICT DO NOTHING;
DELETE FROM app.variant_option_values WHERE tenant_id='11111111-1111-4111-8111-111111111111' AND product_id='33333333-3333-4333-8333-333333333337';
DELETE FROM app.product_variants WHERE tenant_id='11111111-1111-4111-8111-111111111111' AND product_id='33333333-3333-4333-8333-333333333337';
-- Clear ONLY this disposable fixture product's variants to repeat the option test.
DELETE FROM app.variant_option_values WHERE tenant_id='11111111-1111-4111-8111-111111111111' AND product_id='33333333-3333-4333-8333-333333333333';
DELETE FROM app.product_variants WHERE tenant_id='11111111-1111-4111-8111-111111111111' AND product_id='33333333-3333-4333-8333-333333333333';
\set ON_ERROR_STOP on
BEGIN;
SELECT set_config('app.tenant_id','11111111-1111-4111-8111-111111111111',true);
VALUES('11111111-1111-4111-8111-111111111111','66666666-6666-4666-8666-666666666666','local','fixture-pinned-only',sha256('c07-pin'::bytea),1,'ready') ON CONFLICT DO NOTHING;
-- Unverified rows whose hash/size match uploads in the media HTTP gate. Reset on
-- every run so the staging takeover and the deleting refusal are both exercised.
  sha256('\x89504e470d0a1a0a0000000d4948445200000001000000010802000000907753de0000000c4944415478da636064620600000e0007e99237d40000000049454e44ae426082'::bytea),69,'staging'),
 ('11111111-1111-4111-8111-111111111111','66666666-6666-4666-8666-666666666668','s3','fixture-deleting',
  sha256('\x89504e470d0a1a0a0000000d4948445200000001000000010802000000907753de0000000c4944415478da63606165030000200010851878a00000000049454e44ae426082'::bytea),69,'deleting')
ON CONFLICT (tenant_id,id) DO UPDATE SET backend='s3',storage_key=EXCLUDED.storage_key,status=EXCLUDED.status;
VALUES('11111111-1111-4111-8111-111111111111','55555555-5555-4555-8555-555555555555','66666666-6666-4666-8666-666666666666','pinned.png','image/png','public') ON CONFLICT DO NOTHING;
VALUES('11111111-1111-4111-8111-111111111111','88888888-8888-4888-8888-888888888888','77777777-7777-4777-8777-777777777777','C07 release','en') ON CONFLICT DO NOTHING;
VALUES('11111111-1111-4111-8111-111111111111','88888888-8888-4888-8888-888888888888','99999999-9999-4999-8999-999999999999',1,'c07','{}',sha256('c07'::bytea)) ON CONFLICT DO NOTHING;
SELECT '11111111-1111-4111-8111-111111111111'::uuid,'88888888-8888-4888-8888-888888888888'::uuid,'99999999-9999-4999-8999-999999999999'::uuid,'55555555-5555-4555-8555-555555555555'::uuid
WHERE NOT EXISTS(SELECT FROM app.site_release_media WHERE tenant_id='11111111-1111-4111-8111-111111111111' AND release_id='99999999-9999-4999-8999-999999999999');
SELECT app.publish_release('11111111-1111-4111-8111-111111111111','88888888-8888-4888-8888-888888888888','99999999-9999-4999-8999-999999999999',NULL)
WHERE (SELECT published_release_id FROM app.sites WHERE tenant_id='11111111-1111-4111-8111-111111111111' AND id='88888888-8888-4888-8888-888888888888') IS NULL;
COMMIT;
